import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../../core/data/transaction_repository.dart';
class ReportsPage extends StatefulWidget{const ReportsPage({super.key,this.businessId});final String? businessId;@override State<ReportsPage> createState()=>_ReportsPageState();}
class _ReportsPageState extends State<ReportsPage>{final _repo=TransactionRepository();late Future<DashboardMetrics> _future;@override void initState(){super.initState();_future=widget.businessId==null?Future.value(const DashboardMetrics(todayRevenue:0,todayTransactions:0,recentTransactions:[])):_repo.loadDashboard(widget.businessId!);}@override Widget build(BuildContext context){final c=NumberFormat.currency(locale:'id_ID',symbol:'Rp ',decimalDigits:0);return FutureBuilder<DashboardMetrics>(future:_future,builder:(context,s){final m=s.data??const DashboardMetrics(todayRevenue:0,todayTransactions:0,recentTransactions:[]);return ListView(padding:const EdgeInsets.all(16),children:[const Text('Laporan',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),const SizedBox(height:8),Card(child:ListTile(leading:const Icon(Icons.today),title:const Text('Omzet Hari Ini'),trailing:Text(c.format(m.todayRevenue)))),Card(child:ListTile(leading:const Icon(Icons.receipt_long),title:const Text('Transaksi Hari Ini'),trailing:Text(m.todayTransactions.toString()))),const Card(child:ListTile(leading:Icon(Icons.calendar_month),title:Text('Laporan Bulanan'),subtitle:Text('Tahap berikutnya'))),const Card(child:ListTile(leading:Icon(Icons.inventory_2_outlined),title:Text('Stok Produk'),subtitle:Text('Tahap berikutnya')))]);});}}
